private SimulcastLockResponse doCreateSimulcastLock(request, businessDay, atMs, channelIds) {
    if (repo.findAsset(request.assetId()).isEmpty()) {
        throw ApiException.notFound("素材不存在: " + request.assetId());
    }
    // 按字典序锁定全部频道行，与单频道草稿替换/插播创建串行，避免并发漏判与死锁。
    for (String channelId : channelIds) {
        repo.lockChannelForUpdate(channelId);
    }
    List<SimulcastChannelFailure> failures = new ArrayList<>();
    Map<String, GrantRow> selectedGrants = new LinkedHashMap<>();
    for (String channelId : channelIds) {
        Optional<ChannelRow> channel = repo.findChannel(channelId);
        if (channel.isEmpty()) { failures.add(new SimulcastChannelFailure(channelId, "CHANNEL_NOT_FOUND", "频道不存在")); continue; }
        if (repo.findDraft(channelId, businessDay).isEmpty()) { failures.add(... "DRAFT_NOT_FOUND", "频道在该业务日无可用草稿"); continue; }
        boolean occupiedBySegment = repo.findDraftSegments(channelId, businessDay).stream()
                .anyMatch(s -> s.startMs() <= atMs && atMs < s.endMs());
        if (occupiedBySegment) { failures.add(... "SEGMENT_OCCUPIED", ...); continue; }
        if (!repo.findActiveOverridesAt(channelId, atMs).isEmpty()) { failures.add(... "OVERRIDE_OCCUPIED", ...); continue; }
        if (repo.existsActiveMemberAt(channelId, businessDay, atMs)) { failures.add(... "SIMULCAST_OCCUPIED", ...); continue; }
        List<GrantRow> covering = repo.findCoveringGrantsForUpdate(channelId, request.assetId(), atMs, atMs + 1);
        Optional<GrantRow> grant = covering.stream().filter(g -> !g.revoked()).findFirst();
        if (grant.isEmpty()) { failures.add(... "NO_COVERING_GRANT", ...); continue; }
        selectedGrants.put(channelId, grant.get());
    }
    if (!failures.isEmpty()) {
        throw new SimulcastLockException("SIMULCAST_VALIDATION_FAILED",
                "联播锁定校验失败，涉及 " + failures.size() + " 个频道", failures);
    }
    long createdAtMs = nowMs();
    try {
        repo.insertSimulcastGroup(request.simulcastKey(), businessDay, request.assetId(), atMs, channelIds.size(), createdAtMs);
    } catch (DuplicateKeyException e) {
        throw ApiException.conflict("DUPLICATE_SIMULCAST_KEY", "联播组 simulcastKey 已存在: " + request.simulcastKey());
    }
    List<SimulcastPlaceholderResponse> placeholders = new ArrayList<>();
    for (String channelId : channelIds) {
        String placeholderSegmentId = UUID.randomUUID().toString();
        GrantRow grant = selectedGrants.get(channelId);
        try {
            repo.insertSimulcastMember(request.simulcastKey(), channelId, businessDay, placeholderSegmentId, grant.id(), request.assetId(), atMs, createdAtMs);
        } catch (DuplicateKeyException e) {
            throw new SimulcastLockException("SIMULCAST_VALIDATION_FAILED", ..., List.of(new SimulcastChannelFailure(channelId, "SIMULCAST_OCCUPIED", "该时刻已被其他联播组占位")));
        }
        placeholders.add(new SimulcastPlaceholderResponse(request.simulcastKey(), channelId, placeholderSegmentId, request.assetId(), request.at(), grant.id()));
    }
    return new SimulcastLockResponse(request.simulcastKey(), businessDay.toString(), request.assetId(), request.at(), SimulcastStatus.ACTIVE, placeholders, null, null, atMs(createdAtMs));
}
