    // ---------- 撤销时间窗：开始播出后 409 ----------

    @Test
    void revokeAfterStartRejected() throws Exception {
        Ctx ctx = newContext(2, PAST_DAY);
        String key = ctx.key("past");
        createLock("r1", key, ctx.channels, ctx.asset, PAST_DAY, PAST_AT)
                .andExpect(status().isOk());
